      'Application questions test whether you can run the passage\u2019s principle on new facts. The passage\u2019s principle, stated in the final paragraph, is that minimalism is "best understood ... as a rebuttable default": decide narrowly unless there is good reason not to. The paragraph even names the exception that fits this scenario — "disputes, such as those requiring lower courts to administer a workable standard across thousands of cases, genuinely demand breadth." The hypothetical stipulates exactly that: no narrow ground is available and lower courts need a comprehensive standard. So the presumption is rebutted and the court should rule broadly. Choice A applies minimalism as an absolute rule, which the passage explicitly rejects. Choice B invents a dodge — declining to decide — that appears nowhere in the passage. Choice D misattributes a pro-maximalist legitimacy claim to the passage; legitimacy is a minimalist argument. Choice E invents a procedural hybrid the passage never discusses. Only C correctly applies the rebuttable-default framework to the stipulated facts.',
    choiceExplanations: [
      'Tempting if you remember the minimalist thesis but forget the conclusion — this is the wrong-viewpoint trap in application form. The passage explicitly rejects minimalism "as a universal prescription"; applying it absolutely here ignores the rebuttable-default qualification.',
      'Unsupported. The passage never suggests courts should decline to decide hard cases or wait for legislatures to clarify constitutional provisions. This invents a remedy the author does not discuss.',
      'Correct. The scenario matches the final paragraph\u2019s stated exception — cases "requiring lower courts to administer a workable standard" that "genuinely demand breadth" — so the rebuttable presumption for narrowness is overcome.',
      'Wrong-viewpoint: the passage argues legitimacy favors minimalism (modest decisions make courts look less political), not maximalism. This choice flips which side the legitimacy rationale supports.',
      'Unsupported. The passage never proposes split narrow/broad opinions or advisory discussions; this invents a procedural solution rather than applying the passage\u2019s actual principle. On application questions, any choice proposing machinery the passage never discusses is automatically suspect, no matter how clever it sounds.',
    ],
