      'The inference must be anchored in what the passage actually says about why bargaining was legitimized. Paragraph 1 gives a causal story: nineteenth-century courts "treated plea bargaining as a sordid practice to be discouraged," and it moved "from the shadows into the open" only when "urban caseloads swelled beyond anything a trial-centered system could absorb." Brady\u2019s language — an "essential component of the administration of justice" — speaks to systemic indispensability, not to bargaining\u2019s intrinsic virtues. Choice E draws the licensed inference: legitimation was necessity-driven. Choice A is the opposite of paragraph 1, which says judges regarded the practice as improper. Choice B is half-right: its first half restates paragraph 3 (defendants who cannot afford counsel are "least able to call the prosecution\u2019s bluff"), but its prescription — barring such defendants from plea agreements — is invented, and paragraph 5 undercuts it by noting few defendants would thank reformers for forcing a trial gamble. Choice C inverts the paragraph\u2019s logic, replacing necessity with enthusiasm. Choice D is unsupported speculation — the passage never discusses what would happen if the trial penalty were eliminated entirely.',
