      'This inference is licensed by the passage\u2019s own contrast structure. Paragraph 3 builds the moral critique around a specific application: "the deliberate occupation of a neighbor\u2019s unused strip of land in hopes of eventually claiming it," arguing that when evidentiary and economic justifications weaken, "what remains is a rule that teaches citizens that persistent boundary-pushing pays." Paragraph 4 then blunts the critique by arguing the typical case is different — good-faith mistakes hedged by strict requirements — and that the evidentiary rationale survives for genuine boundary disputes over "decades-old surveys and vanished landmarks." Put together, the passage implies the critique\u2019s strength varies with the facts: strongest against calculating opportunism, weakest against good-faith mistakes and stale claims. Choice E names the opportunism case. Choice A names a case where paragraph 4 says the evidentiary rationale still holds — the critique is weakest there. Choice C names the good-faith case the defense covers. Choice D names exempted land, where the doctrine doesn\u2019t apply at all. Choice B describes a situation where the doctrine\u2019s requirements (continuous, unchallenged possession) wouldn\u2019t even be met.',
