      'Map the passage\u2019s movement: paragraph 1 introduces the unreliable narrator via Booth and James\u2019s governess; paragraphs 2–3 advance the counter-claim that unreliability is a reader\u2019s judgment, supported by the observation that readers persistently disagree; paragraph 4 gives the traditionalist reply that unreliability names authorial design; paragraph 5 draws the pedagogical moral — the inference-based approach teaches evidence-weighing better than label-hunting. Choice B contains all four stages. Choice A is too-strong: the passage never declares the concept incoherent or calls for abandonment; it ends by endorsing a better way of teaching it. Choice C takes a side in the governess debate the passage deliberately leaves open ("may be a ghost story, a case study in self-deception, or both"). Choice D inverts paragraph 3\u2019s use of disagreement, which is evidence about where unreliability lives, not proof that criticism is futile. Choice E is the opposite of paragraphs 2–3, which argue unreliability is not a stable textual property.',
