    stimulus: '',
    passageId: 'rc-p05',
    stem: 'Two students disagree about whether a novel\u2019s narrator is unreliable. One cites contradictions between the narrator\u2019s account and other characters\u2019 reports; the other cites details suggesting the narrator is sincere but mistaken about key events. According to the passage\u2019s analysis, this disagreement best illustrates the claim that',
