    stimulus: '',
    passageId: 'rc-p06',
    stem: 'Which one of the following best expresses the main point of the passage?',
    choices: [
      { text: 'Narrative history has been decisively refuted by the Annales school and should no longer be practiced by serious historians.' },
      { text: 'Narrative, structural, and microhistorical approaches each answer a different explanatory question; the historian\u2019s task is matching the scale of explanation to the question' },
      { text: 'The fall of Rome was caused exclusively by weak emperors and invading armies, as narrative historians have always maintained without serious challenge.' },
      { text: 'Microhistory has resolved the debate between narrative and structural history by proving that structures never constrain human action under any circumstances whatsoever.' },
      { text: 'Fernand Braudel\u2019s study of the Mediterranean is the only historical work that has ever successfully explained change.' },
    ],
    correctIndex: 1,
    explanationQuick:
      'The passage surveys narrative history (paragraph 1), the Annales structural challenge (paragraph 2), the critique of structuralism (paragraph 3), the microhistorical synthesis (paragraph 4), and an ecumenical conclusion (paragraph 5). Only choice B captures the survey plus the "match the scale to the question" verdict.',
    explanationWalkthrough:
      'The passage\u2019s structure is a three-position survey with a synthesizing conclusion. Paragraph 1: narrative explanation as artful arrangement of events. Paragraph 2: the Annales structuralist challenge (Braudel, deep structures). Paragraph 3: the critique (structures explain continuity better than change; selection of structures is itself interpretive). Paragraph 4: microhistory as a third way (the miller, structures constraining without determining). Paragraph 5: the ecumenical verdict — each approach answers a different version of the question, so match scale to question. Choice B is the only answer with all three approaches and the concluding prescription. Choice A is the opposite of the conclusion, which rehabilitates narrative history. Choice C mistakes an illustrative example for a thesis. Choice D is too-strong and inverts paragraph 4, which says structures "constrain without determining" — not that they never constrain. Choice E absurdly elevates one example into exclusivity the passage never suggests.',
    choiceExplanations: [
      'Opposite. The conclusion explicitly rehabilitates narrative history as answering "how we got from one event to the next"; nothing is "decisively refuted" or abandoned. The ecumenical conclusion rehabilitates rather than refutes narrative history, so any refutation narrative inverts the passage.',
      'Correct. It names all three approaches and the final paragraph\u2019s prescription: each answers a different version of the explanation question, so match the scale to the question.',
      'Scope-shift. The fall of Rome is a passing illustration of narrative history\u2019s style, not the passage\u2019s thesis; "exclusively" is also far stronger than anything asserted.',
      'Too-strong and inverted. Paragraph 4 says structures "constrain without determining" — they do constrain. "Never constrain" flips the microhistorical claim. Constrain-without-determining is the microhistorical slogan; dropping either half distorts it into something the passage never claims.',
      'Unsupported. Braudel\u2019s study is presented as the most famous example of structural history, not as the sole successful explanation of change. Braudel’s study exemplifies structural history; elevating one example into exclusivity is an unsupported leap.',
    ],
    generalLesson:
      'Survey passages that end ecumenically ("each answers a different question") punish answers that crown one side the winner — the main point is the pluralism, not the victor.',
