    explanationWalkthrough:
      'The detail is stated nearly verbatim in paragraph 2, where Braudel\u2019s work exemplifies the Annales elevation of deep structures over events. Choice D matches. Choice A is the opposite: the study is famous precisely for demoting kings. Choice B confuses Braudel\u2019s macro-structural study with the microhistory examples of paragraph 4 (the Pyrenean village belongs to a different historian\u2019s work). Choice C inverts Braudel\u2019s position — he is the leading anti-narrative figure in the passage. Choice E inverts the study\u2019s content: mountains and seas are central to it, so it cannot have proved geography irrelevant. Detail success here is a matter of keeping the three approaches\u2019 exemplars straight. In survey passages, keep each school’s flagship example labeled, since distractors routinely swap exemplars between positions.',
