      'Keyword-match. The Pyrenean village heresy trial is paragraph 4\u2019s microhistory example, not Braudel\u2019s Mediterranean study. The village trial belongs to paragraph 4’s microhistory; swapping exemplars between schools is this set’s signature trap.',
