    stem: 'A historian writes a book centered on a single nineteenth-century factory town, reconstructing through workers\u2019 letters how one extended family navigated wage labor, religious revivalism, and chain migration, and using that reconstruction to illuminate industrialization\u2019s broader social pressures. According to the passage\u2019s taxonomy, this project most closely exemplifies',
