      'Opposite. The author stresses that effects are "genuine but limited," that flashier interventions deserve "appropriate skepticism," and that guardrails are needed — the reverse of uncritical enthusiasm.',
      'Opposite. The author accepts the psychology as real and defends constrained nudging; "wholly hostile" and "illegitimate manipulation" describe the strongest critics, not the author. Attributing the critics’ language to the author is a wrong-viewpoint trap; the author’s own synthesis is the measured paragraph-5 triad.',
      'Correct. It reproduces paragraph 5\u2019s synthesis: real psychology, genuine-but-limited effects, and ethically constrained practice. Real psychology, limited effects, ethical constraints: the triad is the author’s measured verdict in miniature.',
