      'Wrong-viewpoint. This is the strongest critics\u2019 objection, which the author acknowledges but does not adopt; the author\u2019s framework of guardrails is designed to legitimate nudges like this one.',
      'Opposite. Paragraph 3 explicitly states that default enrollment "works reliably"; the passage never claims defaults are ineffective. Paragraph 3’s explicit reliability ranking makes any ineffectiveness claim about defaults directly contradictory.',
      'Opposite. Paragraph 5 proposes that nudges "be publicly disclosed" — disclosure is a guardrail, not a prohibition. Disclosure is proposed as a guardrail, so treating it as prohibited inverts paragraph 5’s prescription.',
      'Scope-shift. Retirement plans and cafeterias are illustrative examples from paragraph 1; the framework (defaults, guardrails, reflective endorsement) applies generally. Examples illustrate a general framework; confining the framework to its examples is a scope-shift.',
