    passageId: 'rc-p08',
    stem: 'Which one of the following best expresses the main point of the passage?',
    choices: [
      { text: 'Natural resources invariably doom developing countries to slow growth, corruption, and civil war, regardless of their political institutions, policy choices, or historical circumstances.' },
      { text: 'The resource curse has been completely debunked: natural resources never harm economic development, and the entire literature rests on statistical artifacts.' },
      { text: 'The resource curse captures real patterns, but institutions mediate resource effects, so the prescription shifts from fatalism to building transparent revenue institutions before windfalls.' },
      { text: 'Norway and Botswana prove that the resource curse never existed, that economists fabricated the supporting data, and that resource wealth always accelerates development in every case.' },
      { text: 'The only solution to the resource curse is for poor countries to leave all natural resources permanently in the ground, forgoing any extraction revenue whatsoever.' },
    ],
    correctIndex: 2,
    explanationQuick:
      'The passage presents the curse thesis (paragraphs 1–2), the institutionalist critique with its exceptions (paragraph 3), the defenders\u2019 probabilistic refinement (paragraph 4), and the prescriptive synthesis favoring institutional preparation (paragraph 5). Only choice C holds the thesis, the revision, and the shifted prescription together.',
    explanationWalkthrough:
      'The passage\u2019s arc: paragraphs 1–2 establish the resource curse and its mechanisms; paragraph 3 introduces the revisionist challenge (Norway, Botswana — institutions, not resources, are the real variable); paragraph 4 has defenders retreat to a probabilistic claim while conceding the crude version is false; paragraph 5 synthesizes into a prescription — transparent revenue management built before pumping begins. Choice C is the only answer containing the original pattern, the institutionalist revision, and the new prescription. Choice A states the "crude claim" paragraph 4 explicitly says is false. Choice B overstates the critique into total debunking, which neither side endorses. Choice D invents data fabrication, a charge the passage never makes. Choice E states the "early curse literature" counsel that paragraph 5 says has been retired in favor of institutional preparation.',
    choiceExplanations: [
      'Too-strong and contradicted: paragraph 4 explicitly calls the crude "resources always harm" claim false, citing Norway and Botswana as counterexamples. The crude universal claim is the one paragraph 4 explicitly declares false, so it cannot anchor the main point.',
      'Too-strong in the other direction. The critics argue institutions mediate the effect, and defenders retain a probabilistic claim; nobody in the passage says resources "never harm."',
      'Correct. It captures the curse pattern, the institutionalist revision (prior institutional quality as the real variable), and the prescriptive shift from fatalism to preparation. Refinement rather than refutation is the passage’s pattern: keep the probabilistic core while adding the institutional mediator.',
      'Too-strong and unsupported. The exceptions qualify the thesis; the passage never suggests the data were fabricated or that the curse "never existed." Qualification is not fabrication; the exceptions discipline the thesis without impugning the data behind it.',
      'Opposite of the conclusion. Paragraph 5 says the leave-it-in-the-ground counsel has been retired; the synthesis favors institutional preparation, not permanent non-extraction. Retired prescriptions make effective opposite-traps: the passage moves past leave-it-in-the-ground, so reviving it inverts the conclusion.',
    ],
    generalLesson:
      'When a passage refines a thesis rather than killing it ("the probabilistic claim survives"), the main point must preserve the refinement — answers that keep the crude original or declare total victory both fail.',
