      'Paragraph 2 ("The thesis gained influence because the examples seemed so stark") supplies Nigeria, Venezuela, Sierra Leone, and the 1990s cross-country studies — building the case\u2019s credibility just before paragraph 3\u2019s critics attack it. Its job is to make the thesis worth taking seriously.',
    explanationWalkthrough:
      'Function follows placement and framing. The paragraph opens by explaining why "the thesis gained influence": stark cases plus statistical confirmation. Nigeria, Venezuela, Sierra Leone, and the 1990s studies are marshaled to show the pattern is real and well-evidenced — which is exactly what makes the subsequent revisionist critique interesting rather than trivial. If the thesis were obviously baseless, the critics\u2019 refinements wouldn\u2019t matter. Choice B captures this stage-setting role. Choice A misplaces the counterexamples, which belong to paragraph 3. Choice C is the opposite of the paragraph\u2019s claim (diamonds "funded a brutal civil war"). Choice D overstates: the studies are said to "appear to confirm," not to be flawless. Choice E misplaces the institutionalist revision, which is paragraph 3\u2019s job.',
    choiceExplanations: [
      'Scope-shift. The famous counterexamples (Norway, Botswana) appear in paragraph 3 as the critics\u2019 evidence; paragraph 2 builds the thesis up rather than refuting it. Paragraph 2 builds the thesis up; the teardown begins only in paragraph 3, so placement determines function.',
      'Correct. The paragraph\u2019s framing ("gained influence because the examples seemed so stark") and its stark-cases-plus-statistics content establish the thesis\u2019s credibility before the critique. Formidable targets make interesting critiques: the paragraph’s credibility-building is what gives paragraph 3 something to bite on.',
      'Opposite. The paragraph states that Sierra Leone\u2019s diamonds "funded a brutal civil war" — asserting the connection, not denying it. Funded is the paragraph’s verb for the diamond-war link; denying the connection reverses the stated claim.',
      'Too-strong. The studies "appeared to confirm the pattern"; the passage claims apparent confirmation, not methodological flawlessness. Appeared to confirm is hedged deliberately; upgrading hedge to flawlessness is a strength-mismatch trap.',
      'Scope-shift. The institutionalist revision is introduced in paragraph 3; paragraph 2\u2019s job is to establish what is being revised. What is being revised must first be established; paragraph 2’s job is the establishing, not the revising.',
    ],
    generalLesson:
      'In thesis-critique-synthesis passages, the paragraph that piles up supporting evidence right before the critique is doing stage-setting: making the thesis formidable so the critique has something to bite on.',
