    evidenceMap: { supportingParagraphs: [4], supportingSentences: ['if farming made people worse off, why did it conquer the globe', 'Societies were not persuaded by agriculture’s benefits', 'they were captured by its irreversibility'], requiredInference: 'The trap explains the spread of farming despite its costs — the puzzle Diamond’s indictment creates.', whyDistractorsFail: 'A is the transitional-penalty question; B is the ancient-DNA complication; C unasked; D asks about Diamond’s motives, not the trap’s target.' },
    reviewHistory: [
      { date: '2026-09-11', reviewer: 'rc-archetype-rewrite-2026-09-11', verdict: 'validate',
        notes: 'Full passage+question rewrite 2026-09-11: converted rc-p09 to historical-development archetype; hostile-reviewed (no second defensible answer); leakage pass applied.' },
    ],
    stimulus: '',
    passageId: 'rc-p09',
    stem: 'The passage implies that the “demographic trap” argument was developed primarily to answer which one of the following questions?',
    choices: [
      { text: 'How many centuries did the transitional penalty in early farmer health actually last?' },
      { text: 'Did farming spread mainly through the migration of farming peoples or the conversion of foragers?' },
      { text: 'Were Sahlins’s observations of contemporary foraging societies methodologically sound?' },
      { text: 'What motivated Diamond to call agriculture the worst mistake in human history?' },
      { text: 'If farming made early adopters worse off, why did it spread across most of the globe?' },
    ],
    correctIndex: 4,
    explanationQuick:
      'Paragraph 4 opens by naming the exact puzzle the trap answers: “if farming made people worse off, why did it conquer the globe?” The mechanism — yield per acre, population expansion, irreversibility — explains spread without appealing to desirability. Only choice E restates that question.',
    explanationWalkthrough:
      'Paragraph 4 is explicit about the dialectical role of the demographic trap: it “answered the question Diamond’s indictment left hanging,” and the passage states that question verbatim — “if farming made people worse off, why did it conquer the globe?” The trap’s content then matches that question exactly: farming’s advantage was yield per acre rather than welfare, so farming populations grew, displaced or absorbed foragers, and became too numerous to return to foraging. The answer is structural (irreversibility), not evaluative (betterness). Choice E is the direct restatement. The distractors each belong to a different stage of the debate. Choice A asks about the duration of the transitional penalty — the critics’ qualification in paragraph 3, a question about the evidence’s scope, not about farming’s spread. Choice B is the ancient-DNA complication of paragraph 5, which “reframes” the trap rather than motivating it. Choice C raises a methodological worry about Sahlins that the passage never entertains. Choice D asks about Diamond’s personal motives, which the passage never discusses; the trap responds to the logical gap in his argument, not to his biography. The inference is modest — the passage nearly states it — but it requires mapping each question to its proper stage.',
    choiceExplanations: [
      'Wrong stage. The duration of the transitional penalty is the critics’ qualification in paragraph 3 — a question about how to read the skeletal evidence. The demographic trap of paragraph 4 addresses a different puzzle: not how bad or how long the costs were, but why a costly practice spread globally.',
      'Wrong stage. Migration versus conversion is the ancient-DNA complication introduced in paragraph 5, which the passage says “reframes” the demographic trap. It is a later refinement of the trap’s story, not the question the trap was originally developed to answer.',
      'Unsupported. The passage never questions Sahlins’s methodology; it presents his observations as the accepted starting point of the debate’s history. This choice invents a controversy the text does not contain.',
      'Unasked. The passage discusses Diamond’s argument, not his motivations, and the demographic trap responds to the logical gap his indictment leaves — the unexplained global spread — not to anything about Diamond personally.',
      'Correct. The passage states this question nearly verbatim as the one Diamond’s indictment “left hanging,” and the trap’s mechanism — superior yield per acre driving irreversible population growth — is purpose-built to answer it without claiming farming was better for those who adopted it.',
    ],
    generalLesson:
      'Refinements in an intellectual history answer the specific puzzle the previous stage created; match each answer to the question its stage was asking.',
    misconceptionTags: ['wrong-viewpoint'],
    trapTypes: ['unsupported', 'wrong-viewpoint'],
    prerequisites: ['rc-inference', 'rc-passage-structure'],
    estimatedSeconds: 95,
    sourceType: 'original',
    hints: [
      'Paragraph 4 opens by naming the question it answers — what is it?',
      'Which puzzle does Diamond’s indictment leave hanging?',
      'The trap explains spread, not health timelines or motives.',
    ],
    labels: { topic: 'origins of agriculture' },
