    stimulus: '',
    passageId: 'rc-p09',
    stem: 'The discussion of the Cohen and Armelagos volume (paragraph 3) functions primarily to',
    choices: [
      { text: 'refute Diamond’s claim by showing that the skeletal evidence for early farmer ill-health was weaker than he had supposed.' },
      { text: 'introduce the demographic mechanism that explains why farming spread globally despite its heavy costs to individuals.' },
      { text: 'argue that bioarchaeological evidence is too unreliable to support any conclusions about early farmer health.' },
      { text: 'demonstrate that Sahlins’s observations of contemporary foraging peoples were fundamentally mistaken.' },
      { text: 'show how Diamond\u2019s provocation became a research program whose success yielded the first qualification of his case' },
    ],
    correctIndex: 4,
    explanationQuick:
      'Paragraph 3 does two things at once: the 1984 volume assembles worldwide studies confirming the skeletal pattern — turning Diamond’s provocation into a research program — and that deeper evidence base then produces the transitional-penalty qualification. Only choice E captures this dual function.',
    explanationWalkthrough:
      'Function questions ask what a paragraph does in the passage’s architecture, and paragraph 3 has a deliberately double-edged role in this intellectual history. On one edge, the Cohen and Armelagos volume consolidates Diamond’s position: studies “from every continent” show the same pattern of shrinking stature, dental disease, and anemia at the agricultural transition, which is what the passage means by saying “the skeletal evidence became a research program.” Diamond’s essay is no longer a lone provocation; it has an empirical literature behind it. On the other edge, the passage explicitly says “the deeper evidence base also produced the first major qualification” — the transitional-penalty argument that later farming societies recovered and surpassed forager health. The paragraph thus advances and complicates the indictment in the same movement, shifting the debate’s center of gravity from whether early farming hurt to how long the hurt lasted. Choice E names both edges. Choice A gets the paragraph backwards: the volume confirms, not refutes, the pattern. Choice B belongs to paragraph 4’s Boserup-inspired demographic mechanism. Choice C invents a skepticism about bioarchaeology the passage never expresses. Choice D misattributes the paragraph’s target — Sahlins is not under discussion here.',
    choiceExplanations: [
      'Opposite. The volume is presented as confirming the skeletal pattern across continents, which strengthens rather than weakens Diamond’s empirical base. The paragraph’s qualification concerns the evidence’s interpretation (transitional penalty), not its reliability.',
      'Wrong paragraph. The demographic mechanism — yield per acre, expansion, irreversibility — is the work of paragraph 4’s Boserup tradition. Paragraph 3 is about the skeletal evidence and its first qualification, not about why farming spread.',
      'Unsupported. The passage never questions the reliability of bioarchaeological evidence; it treats the skeletal findings as the debate’s shared factual ground. This choice invents a methodological skepticism the text does not contain.',
      'Wrong figure. Sahlins’s observations of living foragers are not revisited or challenged in paragraph 3, which concerns the skeletal evidence and Diamond’s case. The paragraph’s dialectical partner is Diamond, not Sahlins.',
      'Correct. It captures the paragraph’s double movement: consolidation (the 1984 volume turning scattered findings into a worldwide research program) and self-generated qualification (the deeper evidence producing the transitional-penalty response). Both halves are stated explicitly in the text.',
    ],
    generalLesson:
      'In intellectual-history passages, a single stage often both consolidates and qualifies the previous one; function answers must capture both movements.',
