    stimulus: '',
    passageId: 'rc-p09',
    stem: 'Suppose a historian argues that industrialization was “a catastrophe for the workers who lived through it,” citing falling life expectancy in early factory towns, and critics reply that later industrial societies surpassed pre-industrial health. This exchange most closely parallels which stage of the debate described in the passage?',
    choices: [
      { text: 'Sahlins’s affluent-forager thesis and Diamond’s popularization of that thesis two decades later.' },
      { text: 'The Boserup-inspired demographic explanation for why farming spread despite its costs to individuals.' },
      { text: 'The ancient-DNA finding that farming spread partly through migration, reframing the demographic trap.' },
      { text: 'The current convergence on specifying trade-offs between individual welfare and collective capability.' },
      { text: 'Diamond\u2019s skeletal indictment and the “transitional penalty” qualification raised against it' },
    ],
    correctIndex: 4,
    explanationQuick:
      'The hypothetical has the exact shape of paragraphs 2–3: a catastrophe indictment grounded in bodily evidence (skeletons / life expectancy), met by the reply that the damage was transitional and later societies recovered. Choice E names that pair; the other stages concern different questions.',
    explanationWalkthrough:
      'Application questions test whether the reader has abstracted the debate’s structure, not just memorized its content. The hypothetical is constructed to mirror paragraphs 2 and 3 point for point: an indictment (“catastrophe for the workers”) supported by bodily evidence of early suffering (falling life expectancy, like the skeletal evidence of shorter, sicker farmers), answered by critics who invoke later recovery (later industrial societies surpassing pre-industrial health, like the transitional-penalty claim that later agricultural societies surpassed forager outcomes). The passage even supplies the bridge: the transitional-penalty critics compare judging agriculture by its first millennia to “judging industrialization by the slums of the 1840s” — the analogy is nearly the passage’s own. Choice E is the match. Choice A misdescribes the Sahlins–Diamond relationship (Diamond did not popularize Sahlins’s thesis; he converted it into an indictment). Choice B addresses a different question — why farming spread — which the hypothetical never raises. Choice C is the DNA complication, about migration versus conversion, with no analogue in the hypothetical. Choice D is tempting because the hypothetical involves a trade-off-like weighing, but the passage’s current stage is about specifying trade-offs as the debate’s endpoint, whereas the hypothetical replays the earlier indictment-and-reply exchange specifically.',
    choiceExplanations: [
      'Mismatch. Diamond did not popularize Sahlins’s thesis; the passage says he “converted Sahlins’s suggestion into an indictment” — a sharper, different claim. The hypothetical’s structure (indictment plus transitional-penalty reply) does not map onto the Sahlins-to-Diamond succession.',
      'Mismatch. The demographic explanation answers why a costly practice spread globally; the hypothetical exchange is about whether the costs were permanent or transitional. Different question, different stage.',
      'Mismatch. The ancient-DNA finding concerns migration versus conversion in farming’s spread. The hypothetical contains no analogue — no new evidence reframing the mechanism, only an indictment and a recovery reply.',
      'Near-miss. The current stage does involve weighing costs against capabilities, but the hypothetical’s specific shape — catastrophe claim from early bodily evidence, answered by later-recovery evidence — is the paragraph 2–3 exchange, not the passage’s endpoint synthesis. The analogy must match the exchange’s structure, not just its theme of costs and benefits.',
      'Correct. The mapping is exact: bodily evidence of early suffering (skeletons / life expectancy) supporting a catastrophe indictment (Diamond / the historian), met by the transitional-penalty reply (later agricultural / industrial societies recovered and surpassed the baseline). The passage itself invites this parallel with its 1840s-slums comparison.',
    ],
    generalLesson:
      'To apply a debate’s structure, match the dialectical shape — claim type plus reply type — not just the topic; each stage of an intellectual history has a distinctive fingerprint.',
