    stem: 'Which one of the following best expresses the main point of the passage?',
    choices: [
      { text: 'Language determines the boundaries of thought, so that speakers of different languages inhabit entirely different cognitive worlds with no shared perceptual foundation beneath linguistic differences.' },
      { text: 'Linguistic research has proven that language has no effect whatsoever on cognition, and every reported Whorfian finding is a methodological artifact.' },
      { text: 'The strong determinist thesis is abandoned, but color, space, and time research supports a modest neo-Whorfian claim: language shapes perception below conscious deliberation, atop a shared cognitive base' },
      { text: 'Russian speakers are cognitively superior to English speakers because their language has more color terms, giving them measurably better reasoning abilities across every tested domain.' },
      { text: 'The only scientifically respectable position is that grammar is merely a vehicle for expressing pre-existing thought, with no influence on cognition at all.' },
    ],
    correctIndex: 2,
    explanationQuick:
      'Paragraph 1 abandons strong determinism and states the modest thesis; paragraphs 2–4 test it (evidence, skeptical objections, narrowed defense); paragraph 5 synthesizes: universal foundation plus habitual linguistic tuning. Only choice C contains the rejection, the evidence-based modest claim, and the synthesis.',
    explanationWalkthrough:
      'The passage\u2019s arc: paragraph 1 distinguishes the abandoned strong thesis (language determines thought) from the revived weak one (language "habitually nudges" it); paragraph 2 gives the color/space/time evidence; paragraph 3 gives the skeptics\u2019 methodological objections; paragraph 4 narrows the neo-Whorfian claim to habitual, below-deliberation influence; paragraph 5 synthesizes — "shared universal foundation ... overlaid with habitual tunings." Choice C is the only answer with all three elements. Choice A states the abandoned strong thesis — the opposite of the passage\u2019s position. Choice B is the opposite of paragraphs 2 and 4, which defend real (if small) effects. Choice D invents cognitive superiority; the passage reports millisecond discrimination advantages, not superiority. Choice E states the skeptics\u2019 extreme, which paragraph 4\u2019s narrowed defense and paragraph 5\u2019s synthesis both move beyond.',
    choiceExplanations: [
      'Opposite. Paragraph 1 explicitly says the strong version "was largely abandoned by linguists decades ago as both untestable and implausible." Abandoned-as-untestable is paragraph 1’s verdict on the strong thesis, making its endorsement impossible.',
      'Opposite. Paragraphs 2 and 4 defend genuine (if modest) linguistic effects on cognition; "no effect whatsoever" contradicts them. Modest-but-genuine effects are defended in paragraphs 2 and 4; zero-effect claims contradict both.',
      'Correct. It captures the abandonment of determinism, the modest habitual-influence claim supported by the color/space/time research, and the final universal-foundation-plus-tuning synthesis. Three elements — rejection, modest replacement, universal-plus-tuning synthesis — make this the complete main point.',
      'Unsupported and too-strong. The passage reports faster discrimination of certain shades under specific conditions — milliseconds in lab tasks — not general cognitive superiority. Milliseconds in lab tasks are the passage’s unit of effect; inflating them into general superiority is a scale error.',
      'Opposite of the synthesis. Paragraph 5 concludes grammar is "not just tools we use but environments we inhabit" — more than a mere vehicle for pre-existing thought.',
    ],
    generalLesson:
      'Passages that replace a strong thesis with a modest one punish both extremes: the main point must contain the rejection and the qualified replacement together.',
