      'The detail is conditional and precise: Russian speakers were faster at discriminating shades straddling their language\u2019s light-blue/dark-blue boundary — "but only when they could silently name the colors to themselves; under verbal interference, the advantage vanished." Choice D matches. Choice A invents financial incentives, never mentioned. Choice C invents a language-of-instruction manipulation; the interference manipulation concerned subvocal naming, not the experiment\u2019s language. Choice B describes a different boundary condition (the advantage is defined for straddling shades) rather than the interference finding. Choice E invents sample-size details. Note paragraph 4\u2019s use of this same fact: proponents say the disappearance under interference "demonstrates the mechanism rather than debunking it" — so tracking this detail precisely matters for the argument, not just the question.',
