      'Paragraph 3 is the skeptics\u2019 case, with three distinct objections: effects are "small, fragile, and difficult to replicate" (publication bias); the causal direction is uncertain (habitual attention vs. language); and lab findings are "a far cry from the grand claim that language shapes worldviews." Choice A enumerates all three.',
    explanationWalkthrough:
      'Paragraph 3\u2019s job in the passage\u2019s debate structure is to give the skeptical challenge its full strength before paragraph 4\u2019s neo-Whorfian reply. It advances three objections, not one: (1) methodological fragility — "small, fragile, and difficult to replicate," the expected profile "from publication bias in an exciting research area"; (2) causal direction — the blue advantage might reflect habitual attention or shared environment, "with language merely along for the ride"; (3) scope — even the positive findings show "milliseconds of advantage in laboratory tasks," far from grand worldview claims. Choice A is the only answer containing all three. Choice B is too-strong: the paragraph raises objections, and paragraph 4 answers them — no definitive refutation occurs. Choice C misplaces the experiments, introduced in paragraph 2. Choice D universalizes one objection\u2019s mechanism into "the sole cause of all scientific error." Choice E overstates: the skeptics offer environment as an alternative explanation, not a proof covering "every observed cognitive difference."',
    choiceExplanations: [
      'Correct. It enumerates paragraph 3\u2019s three skeptical objections: replicability/publication bias, causal direction, and the lab-to-worldview scope gap. Three objections inventoried together mark the complete function answer; partial lists are half-right traps.',
      'Too-strong. The paragraph voices objections that paragraph 4 then answers; "definitively refuted" overstates a challenge into a verdict. Challenges awaiting replies are not verdicts; paragraph 4’s existence proves the debate continues.',
      'Scope-shift. The Russian color experiments are introduced in paragraph 2 as the neo-Whorfians\u2019 evidence; paragraph 3 criticizes such findings. Paragraph 2 introduces, paragraph 3 criticizes: misplacing content between them breaks the debate’s structure.',
      'Too-strong and scope-shift. Publication bias is invoked as one concern about this literature, not as the sole cause of all scientific error. One concern about one literature universalized into all science is the scope-shift to reject.',
      'Too-strong. The skeptics propose environmental/habitual-attention alternatives for the observed effects; "prove" and "every observed cognitive difference" exceed their claims. Alternatives proposed are not proofs delivered; prove and every are the overstatements to catch.',
    ],
    generalLesson:
      'Objection paragraphs often contain multiple distinct criticisms — the function answer must inventory all of them, not just the first or most vivid.',
