    stimulus: '',
    passageId: 'rc-p10',
    stem: 'A new study finds that speakers of a language with obligatory future-tense marking save less for retirement than speakers of a language without it — but the savings gap disappears entirely once national savings institutions and economic conditions are statistically controlled. According to the passage, the skeptics would most likely cite this result as illustrating',
    choices: [
      { text: 'a decisive confirmation of strong linguistic determinism, vindicating the neo-Whorfian program against its skeptics' },
      { text: 'the causal-direction problem: the language effect reflected shared institutional factors, with language along for the ride' },
      { text: 'proof that statistical controls are an illegitimate research method that can never support causal conclusions' },
      { text: 'evidence that future-tense marking directly causes national savings institutions to weaken over successive generations' },
      { text: 'the publication-bias problem, since the study was never published in a peer-reviewed journal' },
    ],
    correctIndex: 1,
    explanationQuick:
      'Paragraph 3\u2019s causal-direction objection is exactly this pattern: an apparent linguistic effect that "might reflect not linguistic causation but shared environment," with "language merely along for the ride." When controls for institutions erase the gap, the skeptics\u2019 alternative explanation is vindicated on their terms.',
    explanationWalkthrough:
      'Map the new result onto the skeptics\u2019 objection template. The observed pattern: language feature correlates with behavior (savings). The critical test: controlling for third variables (institutions, economic conditions) eliminates the correlation. The skeptics\u2019 paragraph-3 move predicts precisely this: apparent language effects may reflect "shared environment" rather than "linguistic causation." The vanishing gap under controls is therefore, in the skeptics\u2019 framework, an illustration of the causal-direction problem — the confound, not the language, was doing the work. Choice B states this. Choice A is the opposite: the result weakens the linguistic claim. Choice C inverts the skeptics\u2019 methodology — they would welcome controls as clarifying, not condemn them. Choice D reverses the causal arrow into a claim no one makes. Choice E misfires: the study\u2019s publication status is unstated, and the issue illustrated is confounding, not publication bias.',
    choiceExplanations: [
      'Opposite. A gap that vanishes under institutional controls weakens the linguistic-causation claim; it cannot "decisively confirm" determinism. Vanishing-under-controls weakens causal claims; it cannot confirm the thesis it undermines.',
      'Correct. This is paragraph 3\u2019s causal-direction objection instantiated: the language effect disappears once shared institutional/environmental factors are accounted for — language was "along for the ride."',
      'Opposite. Skeptics rely on precisely such controls to separate causation from correlation; they would endorse the method, not condemn it. Controls are the skeptics’ favored tool for separating causation from correlation, not a method they oppose.',
      'Unsupported and causally reversed. No one in the passage claims grammar causes institutions to weaken; the skeptics\u2019 point runs the other way. Reversed causal arrows — grammar weakening institutions — are claimed by no one in the passage.',
      'Scope-shift. The result illustrates confounding (the causal-direction problem), not publication bias; the study\u2019s publication status is never stated. Confounding and publication bias are distinct objections; the vanishing gap illustrates the former, not the latter.',
    ],
    generalLesson:
      'When a correlation vanishes under controls for third variables, the licensed skeptical inference is confounding — match the new result to the objection whose prediction it fulfills.',
