    correctIndex: 4,
    explanationQuick:
      'Paragraph 3 makes the vampire bat the textbook case of reciprocal altruism: no kinship required, only memory, repeated interaction, and the capacity to withhold help — “donors keep score” and perpetual takers “are eventually refused.” Only choice E describes that mechanism.',
    explanationWalkthrough:
      'Viewpoint questions in a survey passage require inhabiting one position while the distractors speak in the voices of the others. Paragraph 3 defines reciprocal altruism’s requirements precisely: repeated encounters, memory, cheater detection, and punishment by withholding future help — with kinship explicitly not required. The vampire bat case is then described in exactly those terms: donors “keep score,” and bats that accept blood without donating are “eventually refused.” Choice E restates the mechanism completely. Choice A ventriloquizes costly signaling (paragraph 5): display, vigor, attracting mates — the audience logic, which the bat case does not involve. Choice B ventriloquizes kin selection: the passage explicitly says “no kinship is required” for reciprocal altruism. Choice C ventriloquizes group selection: between-colony competition, which paragraph 3 never invokes for the bats. Choice D contradicts the paragraph’s central detail — the bats’ behavior is the opposite of past-insensitive instinct; score-keeping is the whole point. The item earns its difficulty from the viewpoint discipline: four of the five choices are true descriptions of something in the passage, and only one belongs to the asked-about account.',
    choiceExplanations: [
      'Wrong viewpoint. Display of vigor to attract mates and allies is costly signaling’s logic from paragraph 5 (Zahavi; the babblers). The bat case in paragraph 3 involves score-keeping and refusal, not audience-directed display.',
      'Wrong viewpoint. Preferential aid to close relatives is kin selection’s mechanism from paragraph 2. Paragraph 3 explicitly states that reciprocal altruism requires “no kinship” — only memory, repeated interaction, and punishable cheating.',
      'Wrong viewpoint. Colonies of sharers outcompeting other colonies is group selection’s between-group logic from paragraph 4. The bat explanation in paragraph 3 operates entirely within the roost, through dyadic score-keeping.',
      'Contradicted. Paragraph 3’s signature detail is that donors “keep score” and refuse perpetual takers — behavior exquisitely sensitive to past conduct. An instinct unaffected by past behavior is the opposite of the described mechanism.',
      'Correct. It names all three of paragraph 3’s requirements — memory, repeated interaction, withholding future help as punishment — and the bat-specific outcome: takers who never give are eventually refused. This is reciprocal altruism’s fingerprint.',
    ],
    generalLesson:
      'To answer viewpoint questions in survey passages, list each position’s proprietary mechanism first, then match; surface plausibility is not enough.',
