      'Paragraph 5 defines costly signaling’s unique prediction as the audience effect: generosity functions as a display of vigor to onlookers, so “remove the onlookers, and the generosity should fade.” None of the other accounts predicts audience dependence. Only choice E states it.',
    explanationWalkthrough:
      'This inference requires comparing the four accounts’ predictions and isolating what is proprietary to one. Paragraph 5 presents costly signaling’s logic — conspicuous generosity as honest advertisement of quality, attracting mates and allies — and then explicitly marks its distinguishing prediction: “The prediction that distinguishes this account is its audience effect: remove the onlookers, and the generosity should fade.” The inference is that the other three accounts carry no such prediction: kin selection depends on relatedness, not observers; reciprocal altruism depends on the partner’s memory, not third parties; group selection depends on group composition, not audiences. Choice E states the audience effect directly. Choice A is kin selection’s domain condition, not a prediction of signaling. Choice B is reciprocal altruism’s cheater-punishment mechanism. Choice C is the critics’ equivalence objection to group selection from paragraph 4. Choice D invents a group-size prediction the passage never makes. The difficulty is honest: the passage nearly states the answer, but reaching it requires holding all four accounts’ logics in mind simultaneously and checking each against the candidate prediction.',
    choiceExplanations: [
      'Wrong account. Occurrence only among close relatives is kin selection’s condition from paragraph 2, where Hamilton’s rule governs aid to kin. Costly signaling explicitly operates beyond kin — the babblers’ audience includes potential mates and allies, not just relatives — so a relatives-only prediction belongs to a different account entirely.',
      'Wrong account. Excluding non-reciprocators from future exchanges is reciprocal altruism’s punishment mechanism from paragraph 3, where donors keep score and refuse perpetual takers. Costly signaling’s payoff is reputational — mates and allies attracted by display — not the restoration of an exchange relationship.',
      'Wrong account. Formal equivalence to kin selection is the critics’ objection to group selection in paragraph 4, not a prediction of costly signaling. This choice transplants another paragraph’s controversy.',
      'Invented. The passage never discusses group size as a variable for any of the four accounts, let alone as costly signaling’s distinguishing prediction. A trend in which generosity frequency varies with group size appears nowhere in the text and follows from none of the accounts’ stated logics.',
      'Correct. It restates paragraph 5’s explicitly marked distinguishing prediction: because the generosity is a display to an audience, removing the onlookers should make it fade — a consequence none of the other three accounts predicts.',
    ],
    generalLesson:
      'A survey’s “distinguishing prediction” for one position is found by checking which consequence follows from its logic alone and from no other position’s.',
    misconceptionTags: ['wrong-viewpoint'],
    trapTypes: ['wrong-viewpoint', 'unsupported'],
    prerequisites: ['rc-inference', 'rc-passage-structure'],
    estimatedSeconds: 105,
    sourceType: 'original',
    hints: [
      'What does paragraph 5 say “distinguishes this account”?',
      'Do kin selection, reciprocal altruism, or group selection predict any audience effect?',
      'The answer is the consequence that follows from signaling logic alone.',
    ],
    labels: { topic: 'evolution of altruism' },
