    stimulus: '',
    passageId: 'rc-p11',
    stem: 'The final paragraph functions primarily to',
    choices: [
      { text: 'argue that the accumulated evidence has now resolved the long debate decisively in favor of kin selection.' },
      { text: 'introduce a fifth explanatory account of altruism that supersedes the previous four.' },
      { text: 'concede that none of the four accounts can adequately explain the evolution of human cooperation.' },
      { text: 'summarize the empirical evidence supporting multilevel selection over its rivals.' },
      { text: 'reframe the accounts as complementary and pose the question: which account fits a given case' },
    ],
    correctIndex: 4,
    explanationQuick:
      'The final paragraph explicitly reframes the four as “a toolkit rather than a set of rival creeds” and states the field’s new question: not which account is true, but “which fits a given case.” Only choice E captures both the reframing and the new question.',
    explanationWalkthrough:
      'In a survey passage, the final paragraph typically delivers the author’s verdict on the surveyed landscape, and here that verdict is a reframing. The paragraph opens with the toolkit metaphor — “treat these four as a toolkit rather than a set of rival creeds” — which recasts the preceding four paragraphs from a contest into a repertoire. It then assigns each tool its domain: kin selection for aid among relatives, reciprocal altruism for stable non-kin exchange, group selection where group structure does causal work, costly signaling where generosity tracks an audience. The paragraph closes by naming the field’s productive question going forward: “which fits a given case,” with human cooperation as the hard case implicating all four. Choice E contains both halves of this function. Choice A is the opposite: kin selection is one tool among four, not the victor. Choice B invents a fifth account the paragraph never introduces. Choice C misreads the human-cooperation sentence, which says the hardest cases “may implicate all four at once” — the opposite of a concession of failure. Choice D is too narrow: group selection gets one clause in a paragraph about all four.',
    choiceExplanations: [
      'Opposite. The paragraph demotes kin selection from sole champion to one tool among four — “the default for aid among relatives,” not the debate’s winner. A toolkit has no victor.',
      'Unsupported. No fifth account is introduced; the paragraph works entirely with the four already surveyed, assigning each its domain. This choice invents content the text does not contain.',
      'Misstates. The paragraph says hard cases like human cooperation “may implicate all four at once” — an embarrassment of explanatory riches, not a concession that none applies.',
      'Too narrow. Group selection receives a single clause (“for cases where group structure does visible causal work”) within a paragraph whose subject is all four accounts and the field’s new question. This choice mistakes a part for the whole.',
      'Correct. It captures the paragraph’s two moves: the reframing (toolkit, not rival creeds, with each account’s domain specified) and the forward-looking question it enables (which account fits a given case).',
    ],
    generalLesson:
      'Survey closers typically reframe rather than crown: the function answer must name the reframing and the new question it opens.',
