    explanationQuick:
      'Paragraph 1 tells the popular Yellowstone story, paragraph 2 the scientific complications, paragraph 3 the "novel ecosystem" critique, paragraph 4 the defenders\u2019 reply, and paragraph 5 frames the disagreement as epistemological — laboratory standards vs. convergent imperfect evidence weighed against inaction. Only choice E spans that arc.',
    explanationWalkthrough:
      'The passage\u2019s structure: paragraph 1 recounts the famous narrative (wolves → elk → willows → beavers → rivers); paragraph 2 complicates it (confounding factors: drought, winters, hunting, bison; unreplicated "ecology of fear" findings); paragraph 3 adds the critics\u2019 deeper point (rewilding yields novel ecosystems, not restored pasts); paragraph 4 gives the defenders\u2019 reply (convergent evidence, costs of waiting, cultural value); paragraph 5 abstracts the dispute to epistemology — "what counts as sufficient evidence for action under uncertainty." Choice E is the only answer containing the narrative, the skepticism, and the framing move. Choice A is too-strong: the passage says the wolf\u2019s contribution is hard to disentangle, not nonexistent. Choice B mistakes the subject for a manual; no identification guidance is given. Choice C takes the skeptics\u2019 side as the author\u2019s verdict, which paragraph 5 withholds. Choice D is the opposite: the passage says the early story "oversold what was known."',
    choiceExplanations: [
      'Too-strong. The passage argues the wolf\u2019s contribution is confounded and hard to isolate, not that reintroduction had "no ecological effects whatsoever." Confounded and hard to isolate is not nonexistent; the passage’s caution is evidential, not ontological.',
      'Scope-shift. The passage debates cascade claims; it never instructs readers in identifying cascades in the field. Debates are not manuals; no identification guidance is offered anywhere in the passage.',
      'Wrong-viewpoint. Halting projects pending perfect evidence is the skeptics\u2019 position; paragraph 5 presents it as one side of an unresolved epistemological dispute, not the author\u2019s verdict.',
      'Opposite. The passage explicitly states that the early triumphalist story "oversold what was known" — the reverse of unqualified celebration. Oversold is the passage’s verdict on the early story, the direct opposite of unqualified celebration.',
      'Correct. It tracks the full movement: the narrative (1), the scientific complications (2–3), the defense (4), and the final framing as a dispute over evidentiary standards under uncertainty (5).',
    ],
    generalLesson:
      'When a passage ends by abstracting a concrete dispute to a methodological principle, the purpose answer must include that abstraction — it\u2019s the payoff of the whole piece.',
    misconceptionTags: ['strength-mismatch', 'wrong-viewpoint'],
    trapTypes: ['too-strong', 'opposite', 'scope-shift', 'wrong-viewpoint'],
