    passageId: 'rc-p13',
    stem: 'Which one of the following best expresses the main point of the passage?',
    choices: [
      { text: 'The faint young Sun paradox — a dimmer early Sun versus evidence of liquid water — lacks a satisfactory solution, but its persistence has been productive.' },
      { text: 'The faint young Sun paradox has been definitively solved by the discovery of high carbon dioxide levels in ancient atmospheres, ending all scientific debate about early Earth temperatures.' },
      { text: 'Stellar physics is fundamentally mistaken, and the young Sun was actually brighter than the present Sun, invalidating all standard solar models and their predictions.' },
      { text: 'Geologists have fabricated the evidence for liquid water on the early Earth in order to sustain an otherwise untenable research program.' },
      { text: 'The search for habitable exoplanets is a waste of resources motivated by an unsolvable paradox that planetary scientists should abandon.' },
    ],
    correctIndex: 0,
    explanationQuick:
      'Paragraph 1 states the paradox, paragraphs 2–4 survey solutions and their difficulties (greenhouse vs. paleosols, supplementary mechanisms, slushball Earth), and paragraph 5 concludes the paradox "endures" but has been "scientifically productive." Only choice A contains the paradox, the unsatisfactory solutions, and the productivity claim.',
    explanationWalkthrough:
      'The passage\u2019s arc: paragraph 1 poses the contradiction (30% dimmer Sun vs. riverbeds and temperate isotopic signatures); paragraph 2 offers the favored greenhouse solution (CO2, methane); paragraph 3 raises the paleosol objection and surveys supplementary proposals, each creating "new ones" of problems; paragraph 4 considers the radical slushball alternative and its escape-from-ice difficulty; paragraph 5 concludes the paradox "endures" because stellar physics and rock chemistry "refuse to be satisfied simultaneously without strain" — yet this persistence "has sharpened techniques," improved models, and informed exoplanet research. Choice A is the only answer with all three elements. Choice B is the opposite: the paleosol evidence challenges the CO2 solution. Choice C contradicts paragraph 1, which says stellar physics "leaves no room for doubt." Choice D invents fabrication never alleged. Choice E inverts paragraph 5, which presents exoplanet relevance as a benefit, not a waste.',
    choiceExplanations: [
      'Correct. It captures the paradox, the failure of each proposed solution to fully satisfy both constraints, and the concluding claim that the paradox\u2019s persistence has been scientifically productive.',
      'Opposite. Paragraph 3\u2019s paleosol evidence suggests CO2 levels "far lower than the strong-greenhouse models require" — the CO2 solution is challenged, not confirmed. Challenged, not confirmed: the paleosol objection is paragraph 3’s central move against the CO2 solution.',
      'Opposite. Paragraph 1 explicitly states stellar physics "leaves no room for doubt" that the young Sun was dimmer; the passage never questions stellar physics. Undoubted stellar physics is a fixed premise; questioning it would contradict paragraph 1’s explicit statement.',
      'Unsupported. No fabrication of geological evidence is alleged anywhere; the rock record is treated as a genuine constraint throughout. Genuine constraints are the passage’s premise; fabrication allegations would collapse its whole structure.',
      'Opposite. Paragraph 5 cites the faint-star problem\u2019s recurrence around red dwarfs as one of the paradox\u2019s productive payoffs, not as a waste. Productive payoffs, not waste, are paragraph 5’s claim about exoplanet research’s connection to the paradox.',
    ],
    generalLesson:
      'Science passages that end with "productive persistence" want a main point containing both the unsolved problem and its fertility — answers declaring victory or defeat alone both fail.',
