      'The final paragraph has a two-part job: acknowledge endurance ("The paradox endures because every proposed solution is constrained by two independent bodies of evidence ... that refuse to be satisfied simultaneously without strain") and then reframe endurance as fertility ("nevertheless scientifically productive," with three named payoffs: atmospheric-reading techniques, climate models, exoplanet habitability). It closes with the general moral: "A paradox that will not die ... can be more valuable than a problem neatly solved — it keeps an entire field honest." Choice E contains both parts. Choice A misreads: exoplanets illustrate the payoff, not a new solution. Choice B is the opposite: the paragraph argues the paradox is valuable, not uninteresting. Choice C contradicts paragraph 3\u2019s paleosol objection, which the paragraph does not retract. Choice D invents a history-of-physics summary absent from the text.',
    choiceExplanations: [
      'Scope-shift. Exoplanets appear as a beneficiary of paradox-driven research (the faint-star problem "recurs around ... red dwarfs"), not as the source of a new solution.',
      'Opposite. The paragraph argues the enduring paradox is "more valuable than a problem neatly solved," the reverse of calling it uninteresting. More valuable than neatly solved is the paragraph’s comparative claim, the reverse of uninteresting.',
      'Opposite. The paragraph does not revisit or vindicate the greenhouse solution; the paleosol objection from paragraph 3 stands unretracted. Unretracted objections stand; the final paragraph assesses productivity, not greenhouse vindication.',
      'Unsupported. No history of stellar physics is summarized; the paragraph assesses the paradox\u2019s scientific productivity. Productivity assessments are not physics histories; the paragraph’s subject is the paradox’s fertility.',
      'Correct. It captures both moves: the paradox endures under dual constraints, and that endurance has been productive (techniques, models, exoplanets) while enforcing intellectual honesty. Concession plus payoff is the paragraph’s two-part job, and this choice is the only one containing both.',
    ],
    generalLesson:
      'Closing "nevertheless productive" paragraphs convert an unsolved problem into a methodological moral — the function answer must include both the concession (unsolved) and the payoff.',
    misconceptionTags: ['scope-shift', 'wrong-viewpoint'],
    trapTypes: ['opposite', 'unsupported', 'scope-shift', 'supported-nonresponsive'],
