      'Paragraph 1 states the paradox (dim Sun vs. liquid water); paragraph 2 presents the strong-greenhouse solution; paragraph 3 raises the paleosol objection and surveys supplements; paragraph 4 considers the slushball alternative; paragraph 5 assesses the enduring paradox\u2019s productivity. Choice A tracks this five-step sequence.',
    explanationWalkthrough:
      'Map each paragraph\u2019s job: (1) paradox stated — faint Sun vs. geological liquid water; (2) leading solution — enhanced greenhouse (CO2, methane); (3) objection + supplements — paleosols record too little CO2, so ammonia/carbonyl sulfide, lower albedo, or a more massive young Sun are proposed, each with costs; (4) radical alternative — slushball Earth with its deglaciation difficulty; (5) assessment — the paradox endures but productively. Choice A reproduces this sequence exactly. Choice B describes a different passage\u2019s structure (mathematical equivalence debates). Choice C invents archival revision. Choice D invents an experiment and policy implications. Choice E invents ridicule of dissenters and unqualified consensus — the passage\u2019s consensus is precisely what\u2019s missing. Verify skeletons paragraph by paragraph in order, since each clause should correspond to exactly one paragraph’s job.',
