    explanationQuick:
      'Minimalist opinions decide the case at hand and no more, leaving broader questions open. The mechanic who fixes only the reported fault matches that structure exactly: resolve the presenting problem, leave everything else alone.',
    explanationWalkthrough:
      'Analogy questions ask you to carry a structural relationship into a new domain. The passage defines minimalism in its opening paragraphs: judges should "decide no more than the case" before them, because narrow rulings limit the damage when courts err and leave democratic processes room to work. The credited choice reproduces that structure: the mechanic resolves the presenting problem (the fault) while deliberately declining to rebuild systems that are working. Choice C inverts the structure — answering every question in advance is the maximalist impulse the passage contrasts with minimalism. Choice B confuses minimalism\u2019s legitimacy argument with a desire for popularity. Choice D describes failing to finish the job, not declining to overreach: a minimalist court still decides the case fully, just narrowly. Choice E describes inconsistency, not restraint. Only A preserves both halves of the relationship: a complete resolution of the immediate problem and a deliberate refusal to go further.',
    choiceExplanations: [
      'Correct. Minimalism, per paragraphs 1–2, decides the case at hand and no more; the mechanic fixes the reported fault and leaves working systems alone. Both halves of the analogy — full resolution of the presenting problem, deliberate refusal to go further — are preserved.',
      'Wrong mechanism. Minimalism\u2019s legitimacy claim is that narrow rulings avoid the appearance of judicial policymaking, not that courts should follow public opinion. Polling the public imports a popularity rationale the passage never endorses.',
      'Opposite. Answering every conceivable question in advance is the maximalist style the passage contrasts with minimalism — broad rulings that bind future cases. The analogy inverts the relationship instead of reproducing it.',
      'Too weak. A minimalist court still decides the dispute fully; it merely refuses to lay down broad rules. An architect who abandons every floor above the foundation leaves the job undone, which is incompleteness, not restraint.',
      'Irrelevant. Changing rules mid-game describes inconsistency and unpredictability, faults minimalists and maximalists alike would disown. Nothing in the passage ties minimalism to altering standards in the middle of a case.',
    ],
    generalLesson:
      'For analogy items, restate the passage\u2019s relationship in domain-neutral terms first ("resolve the immediate problem completely, decline to go further"), then test each choice against both halves of that template.',
