    explanationWalkthrough:
      'Attitude questions are answered from the author\u2019s own evaluative language, not from the views the author reports. Two markers settle this one. First, paragraph 5 speaks in the author\u2019s voice: "What both sides increasingly accept is that abolition is a fantasy," because no legislature will fund a tenfold expansion of courts. That rules out abolitionist readings (choice A). Second, the author gives the critics\u2019 central objection — the trial penalty that can grow coercive — a full, uncorrected hearing in paragraph 3, and paragraph 4 frames reform as taming "failures of regulation, not of bargaining itself." The author\u2019s own position is thus acceptance of the institution plus insistence on curbs: choice B. Choice C overstates: nothing in the passage celebrates bargaining as an unqualified triumph. Choice D fails because the author clearly endorses regulation, which is a reform position. Choice E inverts paragraph 4, which complains about prosecutors\u2019 "nearly unchecked discretion."',
    choiceExplanations: [
      'Too strong. Abolitionist alarm is exactly what paragraph 5 rejects: "What both sides increasingly accept is that abolition is a fantasy." The author treats the jury-trial ideal as unrecoverable, not as a basis for scrapping the system.',
      'Correct. Paragraph 5 accepts bargaining as ineradicable, while paragraphs 3–4 present the trial penalty as a genuine danger and regulation as the remedy — acceptance paired with concern about coercion.',
      'Too strong. The author catalogs bargaining\u2019s coercive potential at length and calls the plea market "among the least regulated in American law." That is not the voice of someone celebrating an unqualified triumph.',
      'Unsupported. The author endorses a concrete reform agenda — regulating prosecutorial discretion — in paragraph 4. Declining to endorse any reform contradicts the passage\u2019s own prescriptive turn.',
      'Opposite. Paragraph 4 complains that "prosecutors enjoy nearly unchecked discretion over charging and offers," the reverse of deference. The author wants prosecutors constrained, not trusted.',
    ],
    generalLesson:
      'Locate the sentences where the author speaks in propria persona (here, "abolition is a fantasy") and separate them from reported views; attitude choices almost always pair one accurate half with one overstated half.',
