    stem: 'A homeowner has fenced and cultivated a strip of a neighbor\u2019s land for twenty-two years, openly and without permission, honestly believing the strip to be her own, and has paid property taxes on it throughout. The statutory period is twenty years. According to the passage\u2019s account of the doctrine as actually applied, her claim is',
