    correctIndex: 3,
    explanationQuick:
      'The counter-movement relocates unreliability from the text to the reader\u2019s judgment. Spiciness that exists only on the taster\u2019s palate reproduces exactly that relocation from object to perceiver.',
    explanationWalkthrough:
      'The structural move in paragraph 2 is a relocation: a property everyone assigned to the object (the narrator\u2019s unreliability) is reassigned to the perceiver (the reader\u2019s judgment). Paragraph 3 reinforces the point with reader disagreement — one reader\u2019s self-deceived governess is another\u2019s heroic protector. The credited choice performs the identical relocation: spiciness feels like a property of the dish but exists only in the taster\u2019s palate. Choices A, B, and C all run the other way, anchoring the property firmly in the object — the punch line\u2019s wording, the painting\u2019s provenance, the statute\u2019s text — which is the traditionalist position the counter-movement rejects. Choice E describes a different mechanism altogether: belief manufacturing truth by numbers, which is not perception constituting a property but consensus altering reality. Only D keeps the property perceiver-dependent, as the passage\u2019s critics insist unreliability is.',
    choiceExplanations: [
      'Opposite. Locating humor entirely in the punch line\u2019s wording makes the property a feature of the object — precisely the object-centered view the counter-movement is arguing against in paragraph 2.',
      'Opposite. A forgery is fake regardless of any viewer\u2019s judgment; the property inheres in the object. That mirrors the traditionalist account of unreliability, not the reader-centered one the question asks about.',
      'Opposite. Fixing meaning in the enacted text anchors the property in the object and freezes it, whereas the passage\u2019s critics insist the relevant property is produced afresh by each reader\u2019s judgment.',
      'Correct. Spiciness seems to belong to the dish but exists only on the taster\u2019s palate — the same relocation from object to perceiver that the counter-movement performs on unreliability, and it explains why readers disagree.',
      'Different mechanism. A rumor becoming true through widespread belief describes consensus manufacturing reality, not a perceiver-dependent property. Unreliability on the critics\u2019 view is not made true by majority vote.',
    ],
    generalLesson:
      'For analogy items, first state the passage\u2019s move abstractly (here: relocate a property from object to perceiver); three of five choices will typically run the same move in reverse.',
