    correctIndex: 1,
    explanationQuick:
      'The weak neo-Whorfian claim is that language tunes habitual thought without constraining what can be thought. A climate shapes habits and defaults without forcing any single choice — the same soft, statistical influence.',
    explanationWalkthrough:
      'Paragraph 4 gives the claim\u2019s exact strength: language does not constrain "what can be thought" but shapes "what is habitually thought — which distinctions are routinely noticed." The right analogy must therefore be a background influence that biases defaults without determining outcomes. A climate does precisely that to its inhabitants\u2019 habits, so B is correct. The prison (A) and the blueprint (C) are determination relationships — rigid control and exact conformity — which reproduce the strong, abandoned version of Whorfianism the passage says "few now defend." The mirror (E) inverts the direction: it reflects what is already there rather than shaping anything. The coin toss (D) introduces randomness, which is neither shaping nor habitual. Only B keeps the influence real but non-determining, matching the passage\u2019s "both/and" conclusion in paragraph 5, where language overlays habitual tunings on a shared universal foundation.',
    choiceExplanations: [
      'Too strong. A prison rigidly controls movement — a determination relationship. Paragraph 4 explicitly says few now defend the claim that language constrains what can be thought; the prison analogy revives that abandoned strong version.',
      'Correct. A climate shapes habits and defaults without forcing any single choice, which matches the neo-Whorfian claim exactly: habitual tuning of what is routinely noticed, not a cage around what is thinkable.',
      'Too strong. A building erected in exact conformity with a blueprint is determination again — the strong Whorfianism the passage says was abandoned. The neo-Whorfian claim is about habits, not blueprints.',
      'Irrelevant. A coin toss produces outcomes by chance, which is neither shaping nor habitual tuning. Language on the neo-Whorfian view is a systematic influence, the opposite of randomness.',
      'Opposite direction. A mirror reflects what already exists; it shapes nothing. The neo-Whorfian claim is that language actively tunes perception and inference — influence, not reflection.',
    ],
    generalLesson:
      'For analogy items on a weakened thesis, match the strength of the influence first (determining vs. biasing vs. null); most distractors will reproduce the strong version the passage abandoned.',
