    correctIndex: 2,
    explanationQuick:
      'The final paragraph recasts the four accounts as a toolkit: "nature uses them all," and the productive question is which fits a given case — not which account wins. That is exactly C.',
    explanationWalkthrough:
      'The author\u2019s own verdict arrives in the final paragraph: the four accounts are not rival creeds but a toolkit, "the productive question has shifted from which account is true to which fits a given case," and the hardest cases "may implicate all four at once." Choice C restates that synthesis. Choice A is contradicted by the passage itself — kin selection comes with Hamilton\u2019s formal rule (rB > C), and the author never dismisses any account as merely verbal. Choice B inverts the synthesis: the author reports the criticism that group selection may be mathematically equivalent to kin selection and declines to crown any single winner. Choice D is the framing the final paragraph retires — a winner-take-all debate — not the framing the author endorses. Choice E inverts the passage\u2019s last move: the author suggests the hardest cases may need all four, which is confidence in combination, not doubt about each. Only C preserves both the complementarity and the case-by-case method.',
    choiceExplanations: [
      'Unsupported. The passage presents kin selection with Hamilton\u2019s formal inequality and treats all four accounts as scientifically serious. Nothing in the author\u2019s voice dismisses them as loose verbal argument.',
      'Opposite. The author reports critics who call group selection mathematically equivalent to kin selection and never crowns a single account. The synthesis in the final paragraph assigns every account a role.',
      'Correct. The final paragraph\u2019s toolkit framing — "nature uses them all," ask "which fits a given case" — is exactly complementarity plus case-by-case application, with no exclusive winner declared.',
      'Opposite. Treating the accounts as competitors awaiting a decisive experiment is the framing the final paragraph supersedes; the author says the productive question is no longer which account is true.',
      'Half-right inverted. The author is respectful of all four, but the conclusion about hard cases is that they may implicate all four at once — a call for combination, not an expression of doubt.',
    ],
