    correctIndex: 3,
    explanationQuick:
      'The slushball view says the early Earth swung between long glaciations and warm intervals, with the rock record sampling the warm spells. Direct geological evidence of repeated glacial-warm cycles is exactly what would strengthen it.',
    explanationWalkthrough:
      'Application here means identifying what a hypothesis predicts and finding the discovery that matches. Paragraph 4 describes the slushball resolution: the early Earth was not continuously clement but experienced "long intervals of global or near-global glaciation punctuated by warmer episodes," and the liquid-water signatures in the rocks "sample the warm intervals." A discovery of deposits recording repeated glacial-warm cycles is the hypothesis\u2019s signature evidence, so D is correct. Choice A supports the rival strong-greenhouse resolution (paragraph 2), not the slushball. Choice B deepens the paradox the slushball is meant to resolve — a dimmer Sun makes continuous warmth harder, not slushball cycles more likely. Choice C is orthogonal: life\u2019s location of origin does not bear on climate cycles, and paragraph 4 actually speculates life began in ice-covered oceans. Choice E directly contradicts the slushball premise by confirming continuous temperate conditions — it would strengthen the greenhouse camp and kill the slushball.',
    choiceExplanations: [
      'Wrong side. Higher early carbon dioxide supports the strong-greenhouse resolution of paragraph 2, the slushball\u2019s rival. Strengthening a competing explanation does nothing for the hypothesis the question asks about.',
      'Wrong direction. A dimmer young Sun deepens the original paradox — more freezing to explain — without supplying the cyclical thaw mechanism the slushball view requires. It raises the puzzle rather than resolving it.',
      'Irrelevant. Where life originated does not discriminate between climate histories, and paragraph 4 actually imagines life beginning in ice-covered oceans kept liquid by geothermal heat. The choice changes the subject.',
      'Correct. Deposits recording repeated glaciation-thaw cycles are the slushball hypothesis\u2019s signature evidence: "long intervals of ... glaciation punctuated by warmer episodes," with warm spells leaving the visible traces.',
      'Opposite. Continuous temperate conditions for a billion years would vindicate the greenhouse resolution and refute the slushball premise that the planet was mostly frozen. This weakens the target hypothesis.',
    ],
    generalLesson:
      'To strengthen a passage hypothesis, first extract its distinctive prediction (here: cyclical glaciation with warm intervals); discoveries that fit rival hypotheses or deepen the original puzzle are the standard traps.',
