        'The slushball view posits "long intervals of global or near-global glaciation punctuated by warmer episodes" (paragraph 4).',
        'The rival resolution invokes "far higher concentrations of heat-trapping gases," with carbon dioxide "hundreds of times its modern level" (paragraph 2).',
